import * as THREE from 'three/webgpu';
import { mix, vec3, color } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import { createMSDFText } from '@/text';

export default function createNode(config, ctx) {
  // Root group
  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);
  group.name = config.id || 'loop-column-gallery';

  // Design tokens
  const COLORS = {
    background: new THREE.Color('#0b0b10'),
    surface: new THREE.Color('#14141a'),
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38')
  };

  // Geometry constants
  const PLATE_WIDTH = 1.9;
  const PLATE_HEIGHT = 1.2;
  const PLATE_PITCH = 1.5; // vertical spacing
  const PLATE_COUNT = 6;
  const COLUMN_X_OFFSET = 0.9;
  const LOOP_LENGTH = PLATE_COUNT * PLATE_PITCH; // 9.0

  // Load texture (same for all plates – distinct crops assumed handled elsewhere)
  const plateTexture = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');

  // Containers for later reference
  const plates = [];
  const plateFrames = [];
  const accentStrips = [];
  const captionTexts = [];

  // Helper to create a plate mesh
  function createPlate(index) {
    // Plane geometry
    const geometry = new THREE.PlaneGeometry(PLATE_WIDTH, PLATE_HEIGHT);
    // Material using TSL NodeMaterial (standard PBR)
    const material = new THREE.MeshStandardMaterial({
      map: plateTexture,
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
      color: COLORS.paper
    });
    material.needsUpdate = true;

    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(COLUMN_X_OFFSET, -index * PLATE_PITCH, 0);
    mesh.name = `plate-${index}`;
    group.add(mesh);
    plates.push(mesh);

    // Bevel frame (slightly larger plane behind)
    const frameGeom = new THREE.PlaneGeometry(PLATE_WIDTH + 0.06, PLATE_HEIGHT + 0.06);
    const frameMat = new THREE.MeshStandardMaterial({
      color: COLORS.ink,
      roughness: 0.5,
      metalness: 0.5,
      clearcoat: 0.1
    });
    const frame = new THREE.Mesh(frameGeom, frameMat);
    frame.position.set(0, 0, -0.001);
    mesh.add(frame);
    plateFrames.push(frame);

    // Accent strip on left edge (only for the focused plate later)
    const stripGeom = new THREE.PlaneGeometry(0.03, PLATE_HEIGHT);
    const stripMat = new THREE.MeshStandardMaterial({
      color: COLORS.accent,
      emissive: COLORS.accent,
      emissiveIntensity: 0,
      roughness: 0.3,
      metalness: 0.2
    });
    const strip = new THREE.Mesh(stripGeom, stripMat);
    strip.position.set(-PLATE_WIDTH / 2 - 0.015, 0, 0.001);
    mesh.add(strip);
    accentStrips.push(strip);

    // Caption text (will be positioned later)
    const caption = config.textContent.find((t, i) => i === index + 1) || '';
    const captionMesh = createMSDFText({
      atlas: ctx.fontAtlas,
      text: caption,
      fontFamily: 'JetBrains Mono',
      fontSize: 0.13, // scene-unit em height approximated
      fontWeight: 400,
      color: COLORS.ink,
      letterSpacing: 0.08,
      lineHeight: 1.4,
      align: 'left'
    });
    captionMesh.position.set(-1.6, 0, 0.01);
    mesh.add(captionMesh);
    captionTexts.push(captionMesh);
  }

  // Create plates
  for (let i = 0; i < PLATE_COUNT; i++) {
    createPlate(i);
  }

  // Headline text (pinned)
  const headline = createMSDFText({
    atlas: ctx.fontAtlas,
    text: config.textContent[0] || '',
    fontFamily: 'Lora',
    fontSize: 0.62, // scene-unit em height approximated
    fontWeight: 600,
    color: COLORS.ink,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    align: 'left'
  });
  headline.position.set(-1.6, 1.9, 0);
  group.add(headline);

  // Scroll handling
  const scrollState = {
    targetOffset: 0,
    currentOffset: 0,
    tween: null,
    focusTween: null
  };

  function updateLoop() {
    // Apply modulo looping to each plate
    for (let i = 0; i < PLATE_COUNT; i++) {
      const baseY = -i * PLATE_PITCH;
      const y = ((baseY + scrollState.currentOffset) % LOOP_LENGTH + LOOP_LENGTH) % LOOP_LENGTH - LOOP_LENGTH;
      plates[i].position.y = y;
    }

    // Determine focused plate (closest to y=0)
    let closestIdx = 0;
    let minDist = Infinity;
    for (let i = 0; i < PLATE_COUNT; i++) {
      const dist = Math.abs(plates[i].position.y);
      if (dist < minDist) {
        minDist = dist;
        closestIdx = i;
      }
    }

    // Animate focus scaling and accent emissive
    plates.forEach((p, idx) => {
      const targetScale = idx === closestIdx ? 1.06 : 1.0;
      if (!p.userData.scaleTween) {
        p.userData.scaleTween = gsap.to(p.scale, {
          x: targetScale,
          y: targetScale,
          z: targetScale,
          duration: 0.35,
          ease: 'cubic-bezier(0.215,0.61,0.355,1)'
        });
      } else {
        p.userData.scaleTween.kill();
        p.userData.scaleTween = gsap.to(p.scale, {
          x: targetScale,
          y: targetScale,
          z: targetScale,
          duration: 0.35,
          ease: 'cubic-bezier(0.215,0.61,0.355,1)'
        });
      }

      // Accent strip emissive
      const strip = accentStrips[idx];
      const emissiveTarget = idx === closestIdx ? 1.4 : 0;
      if (!strip.userData.emissiveTween) {
        strip.userData.emissiveTween = gsap.to(strip.material, {
          emissiveIntensity: emissiveTarget,
          duration: 0.35,
          ease: 'power2.out'
        });
      } else {
        strip.userData.emissiveTween.kill();
        strip.userData.emissiveTween = gsap.to(strip.material, {
          emissiveIntensity: emissiveTarget,
          duration: 0.35,
          ease: 'power2.out'
        });
      }
    });
  }

  // Expose scroll handler
  group.userData.handlers = {
    scroll(deltaY) {
      // Compute new target offset
      const deltaUnits = deltaY * PLATE_PITCH; // 1 scroll unit => 1.5 scene units
      scrollState.targetOffset = scrollState.currentOffset + deltaUnits;

      // Animate to target with weighted-settle preset (overshoot then settle)
      if (scrollState.tween) scrollState.tween.kill();
      scrollState.tween = gsap.to(scrollState, {
        currentOffset: scrollState.targetOffset,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        onUpdate: updateLoop,
        onComplete: () => {
          // loop back into range to avoid large numbers
          scrollState.currentOffset = ((scrollState.currentOffset % LOOP_LENGTH) + LOOP_LENGTH) % LOOP_LENGTH;
          scrollState.targetOffset = scrollState.currentOffset;
        }
      });
    }
  };

  // Apply cinematic primitives from config
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(group, prim.params);
      }
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    // Kill GSAP tweens
    gsap.killTweensOf(scrollState);
    plates.forEach(p => {
      if (p.userData.scaleTween) p.userData.scaleTween.kill();
      p.geometry.dispose();
      if (p.material.map) p.material.map.dispose();
      p.material.dispose();
    });
    plateFrames.forEach(f => {
      f.geometry.dispose();
      f.material.dispose();
    });
    accentStrips.forEach(s => {
      s.geometry.dispose();
      s.material.dispose();
    });
    if (plateTexture) plateTexture.dispose();
    if (headline) {
      headline.geometry.dispose();
      headline.material.dispose();
    }
    captionTexts.forEach(ct => {
      ct.geometry.dispose();
      ct.material.dispose();
    });
  };

  return group;
}
